'use strict';let csrf='',timer=null;const fields=[['run_id','run_id'],['adjudication','裁決'],['packet_bytes','packet bytes'],['generated_bytes','generated bytes'],['network_bytes','network bytes'],['expected_sha256','expected SHA-256'],['actual_sha256','actual SHA-256'],['verifier_decision','verifier decision'],['total_field_seal','Total Field seal'],['integrity','內容完整性'],['authenticity','來源真實性'],['reason_code','reason code']];async function capabilities(){const r=await fetch('/api/w7tp/v2/capabilities');const c=await r.json();csrf=c.csrf_token;document.querySelector('#json').textContent=JSON.stringify({...c,csrf_token:'[SESSION]'},null,2)}function render(j){document.querySelector('#state').textContent=j.state||'—';const dl=document.querySelector('#result');dl.replaceChildren();for(const[k,label]of fields){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;let v=j[k];if(k==='authenticity'&&v==='UNVERIFIED')v='尚未驗證';dd.textContent=v??'—';dl.append(dt,dd)}const a=document.querySelector('#packet');if(j.packet_ready&&j.state==='PASS'){a.classList.remove('disabled');a.setAttribute('aria-disabled','false');a.href=`/api/w7tp/v2/jobs/${encodeURIComponent(j.run_id)}/packet`;if(!a.dataset.downloaded){a.dataset.downloaded='true';a.click()}}else{a.classList.add('disabled');a.setAttribute('aria-disabled','true');a.removeAttribute('href')}if(!['PASS','HOLD','BLOCK','ERROR'].includes(j.state))timer=setTimeout(()=>poll(j.run_id),400)}async function poll(run){const r=await fetch(`/api/w7tp/v2/jobs/${encodeURIComponent(run)}`);render(await r.json())}document.querySelector('#job').addEventListener('submit',async e=>{e.preventDefault();clearTimeout(timer);const form=new FormData();form.append('source',document.querySelector('#source').files[0]);form.append('intent',document.querySelector('#intent').value);const r=await fetch('/api/w7tp/v2/jobs',{method:'POST',headers:{'X-CSRF-Token':csrf},body:form});render(await r.json())});capabilities();
